extern void convenience_split_memory(unsigned,unsigned char*,unsigned char*,const unsigned char*,const unsigned char*);
extern void convenience_compare(unsigned char*,const unsigned char*,unsigned*);
int main(void) {
  unsigned char input[64], output[48], expected[48];
  for (unsigned test=0;test<35;test++) {
    for (unsigned j=0;j<64;j++) input[j]=(unsigned char)(j*79+test*193);
    /* Include signed zero, NaNs and arbitrary floating representations. */
    if (test==0) { const uint32_t bits[]={0x80000000u,0x7f800001u,0xffc12345u,0x7fc00000u}; memcpy(input,bits,16); }
    {
      unsigned char got[48],want[48];unsigned calls=0;
      convenience_compare(got,input+1,&calls);
      for(unsigned size=1;size<=4;size*=2)for(unsigned j=0;j<16;j+=size) {
        int64_t a,b;
        if(size==1){int8_t x,y;memcpy(&x,input+1+j,1);memcpy(&y,input+17+j,1);a=x;b=y;}
        else if(size==2){int16_t x,y;memcpy(&x,input+1+j,2);memcpy(&y,input+17+j,2);a=x;b=y;}
        else {int32_t x,y;memcpy(&x,input+1+j,4);memcpy(&y,input+17+j,4);a=x;b=y;}
        unsigned base=size==1?0:size==2?16:32;memset(want+base+j,a<b?255:0,size);
      }
      if(calls!=6||memcmp(got,want,48)){fprintf(stderr,"signed less-than aliases pattern %u\n",test);return 4;}
    }
    for (unsigned k=0;k<sizeof(cases)/sizeof(cases[0]);k++) {
      const struct Case *c=&cases[k]; unsigned calls=0;
      memset(output,0xa5,sizeof(output)); memset(expected,0xa5,sizeof(expected));
      c->fn(output+3,input+1,&calls);
      /* The input pointer is deliberately unaligned. */
      for (unsigned j=0;j<c->width;j++) expected[j+3]=c->map[j]<0?0:input[c->map[j]+1];
      if (memcmp(output,expected,sizeof(output)) || calls!=c->calls) { fprintf(stderr,"%s pattern %u calls %u/%u\n",c->name,test,calls,c->calls); return 1; }
      /* Output may alias input. Snapshot the oracle before the call. */
      unsigned char alias[64]; memcpy(alias,input,64); calls=0;
      c->fn(alias+1,alias+1,&calls);
      if (memcmp(alias+1,expected+3,c->width) || calls!=c->calls) { fprintf(stderr,"alias %s pattern %u\n",c->name,test); return 1; }
    }
  }
  long page=sysconf(_SC_PAGESIZE);
  unsigned char *guard=mmap(0,(unsigned long)page*4,PROT_NONE,MAP_PRIVATE|MAP_ANONYMOUS,-1,0);
  if(guard==MAP_FAILED||mprotect(guard,page,PROT_READ|PROT_WRITE)||mprotect(guard+page*2,page,PROT_READ|PROT_WRITE))return 2;
  for(unsigned k=0;k<sizeof(cases)/sizeof(cases[0]);k++) {
    const struct Case*c=&cases[k];if(!c->read_bytes)continue;
    unsigned char*input=guard+page-c->read_bytes,*out=guard+page*3-c->width;
    unsigned char expected[32];unsigned calls=0;
    for(unsigned j=0;j<c->read_bytes;j++)input[j]=(unsigned char)(j*71+13);
    for(unsigned j=0;j<c->width;j++)expected[j]=c->map[j]<0?0:input[c->map[j]];
    c->fn(out,input,&calls);
    if(memcmp(out,expected,c->width)||calls!=c->calls){fprintf(stderr,"guard %s\n",c->name);return 3;}
  }
  for(unsigned kind=0;kind<3;kind++) {
    unsigned char*a=guard+page-16,*b=guard+page*3-16,wanta[16],wantb[16];
    for(unsigned j=0;j<16;j++){a[j]=wantb[j]=(unsigned char)(j*19+53);b[j]=wanta[j]=(unsigned char)(j*73+91);}
    convenience_split_memory(kind,b,a,a,b);
    if(memcmp(a,wanta,16)||memcmp(b,wantb,16)){fprintf(stderr,"split-half guard/alias kind %u\n",kind);return 5;}
  }
  munmap(guard,(unsigned long)page*4);
  puts("PASS construct/broadcast exact bits, unaligned memory, aliases, evaluation count"); return 0;
}
